package com.yeyamo_mobile.api.commerce_service.messaging;
import com.fasterxml.jackson.databind.*;import org.springframework.stereotype.*;import java.time.*;import java.util.*;
@Service public class OutboxService{private final CommerceOutboxRepository repo;private final ObjectMapper json;public OutboxService(CommerceOutboxRepository r,ObjectMapper j){repo=r;json=j;}public void append(String topic,String type,String aggregate,String correlation,Map<String,Object>payload){try{CommerceOutbox e=new CommerceOutbox();e.id=UUID.randomUUID();e.targetTopic=topic;e.eventType=type;e.aggregateId=aggregate;e.correlationId=correlation;e.payload=json.writeValueAsString(Map.of("eventId",e.id,"eventType",type,"correlationId",correlation==null?"":correlation,"payload",payload));e.occurredAt=Instant.now();repo.save(e);}catch(Exception x){throw new IllegalStateException(x);}}}
